/**
 * Drawing Challenge Bank — 120+ creative prompts organized by category & difficulty.
 * Supports instant-load, no-repeat, infinite variety for the Art Studio.
 */

export type DrawingDifficulty = 'Rookie' | 'Brave' | 'Legend';

export interface DrawingPrompt {
  id: string;
  title: { en: string; de: string };
  description: { en: string; de: string };
  category: DrawingCategory;
  difficulty: DrawingDifficulty;
  emoji: string;
  /** Suggested tools/techniques */
  tips?: { en: string; de: string };
}

export type DrawingCategory =
  | 'animals' | 'space' | 'nature' | 'fantasy' | 'food'
  | 'vehicles' | 'underwater' | 'people' | 'buildings'
  | 'bible' | 'holidays' | 'sports' | 'monsters' | 'mashup';

export interface StudioMission {
  id: string;
  title: { en: string; de: string };
  prompt: { en: string; de: string };
  setup: { en: string; de: string };
  reward: string;
  difficulty: DrawingDifficulty;
  timeLimitSec: number;
  goals: { kind: string; count?: number; label: { en: string; de: string } }[];
}

